1	'use strict';
2	
3	const { createHash } = require('node:crypto');
4	const { ConflictError, IntegrityError, NotFoundError, ValidationError } = require('./errors');
5	const replay = require('./replay');
6	const sim = require('./sim');
7	const { Store } = require('./store');
8	
9	/** Canonical JSON used to compare an idempotent retry with the original request. */
10	function canonicalJson(value) {
11	  if (Array.isArray(value)) {
12	    return `[${value.map(canonicalJson).join(',')}]`;
13	  }
14	  if (value && typeof value === 'object') {
15	    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
16	  }
17	  return JSON.stringify(value === undefined ? null : value);
18	}
19	
20	function requestHash(body) {
21	  return createHash('sha256').update(canonicalJson(body)).digest('hex');
22	}
23	
24	/**
25	 * LockstepNet service: deterministic lockstep simulation with rollback replay.
26	 *
27	 * The whole contract follows from three rules:
28	 *   1. a match state is a pure function of (configuration, set of input records);
29	 *   2. an input record is keyed by (tick, unit, command) and applied in a
30	 *      canonical order inside its tick, so arrival order is irrelevant;
31	 *   3. an input for a tick that already ran forces a rollback: the frames from
32	 *      that tick on are rebuilt by replaying the stored input log, which
33	 *      reproduces the hashes that were recorded before the rollback.
34	 */
35	class Lockstep {
36	  constructor(database) {
37	    this.store = new Store(database);
38	  }
39	
40	  close() {
41	    this.store.close();
42	  }
43	
44	  /** Required-key idempotency: repeats return the first result, conflicts are 409. */
45	  idempotent(key, operation, body, action) {
46	    if (typeof key !== 'string' || key.length === 0 || key.length > 200) {
47	      throw new ValidationError('Idempotency-Key header must be a non-empty string of at most 200 characters');
48	    }
49	    const hash = requestHash(body);
50	    return this.store.transaction(() => {
51	      const existing = this.store.getIdempotent(key);
52	      if (existing) {
53	        if (existing.operation !== operation) {
54	          throw new ConflictError('idempotency key was already used for another operation');
55	        }
56	        if (existing.requestHash !== hash) {
57	          throw new ConflictError('idempotency key was already used with a different request body');
58	        }
59	        return existing.response;
60	      }
61	      const response = action();
62	      this.store.putIdempotent(key, operation, hash, response);
63	      return response;
64	    });
65	  }
66	
67	  match(matchId) {
68	    const record = this.store.readMatch(matchId);
69	    if (!record) {
70	      throw new NotFoundError(`match ${matchId} was not found`);
71	    }
72	    return record;
73	  }
74	
75	  config(matchId) {
76	    return this.match(matchId).config;
77	  }
78	
79	  createMatch(raw, key) {
80	    const config = sim.parseConfig(raw);
81	    return this.idempotent(key, `create-match:${config.id}`, raw, () => {
82	      if (this.store.readMatch(config.id)) {
83	        throw new ConflictError(`match ${config.id} already exists`);
84	      }
85	      const state = sim.initialState(config);
86	      state.hash = sim.stateHash(state);
87	      this.store.insertMatch(config, state);
88	      return this.describe(config, state);
89	    });
90	  }
91	
92	  getState(matchId) {
93	    const record = this.match(matchId);
94	    return this.describe(record.config, this.store.readState(matchId));
95	  }
96	
97	  /**
98	   * Public projection of a match: configuration, current deterministic state and
99	   * input-delivery counters.
100	   *
101	   * `missing` counts the input records the match expected but never received:
102	   * one per unit alive at the start of each already simulated tick, minus the
103	   * records that were delivered for that tick.
104	   */
105	  describe(config, state) {
106	    const frames = this.store.readFrames(config.id);
107	    const stats = this.store.readStats(config.id);
108	    let missing = 0;
109	    let settled = 0;
110	    for (const frame of frames) {
111	      const gap = Math.max(0, frame.alive - frame.inputs.length);
112	      missing += gap;
113	      settled += gap === 0 ? 1 : 0;
114	    }
115	    const alive = Object.values(state.units).filter((unit) => unit.health > 0);
116	    const team = (name) => ({ alive: alive.filter((unit) => unit.team === name).length, damage: state.teamDamage[name] });
117	    return {
118	      config: { id: config.id, max_ticks: config.maxTicks, seed: config.seed, units: config.units },
119	      inputs: {
120	        accepted: stats.accepted, duplicates: stats.duplicates, missing,
121	        rejected: stats.rejected, rollbacks: stats.rollbacks, settled,
122	      },
123	      match_id: config.id,
124	      max_ticks: config.maxTicks,
125	      seed: config.seed,
126	      state_hash: state.hash,
127	      status: state.status,
128	      teams: { blue: team('blue'), red: team('red') },
129	      tick: state.tick,
130	      units: Object.values(state.units).sort((left, right) => (left.id < right.id ? -1 : 1)).map((unit) => ({
131	        alive: unit.health > 0, attacking: unit.attacking, health: unit.health,
132	        id: unit.id, position: unit.position, team: unit.team, velocity: unit.velocity,
133	      })),
134	    };
135	  }
136	
137	  /**
138	   * Queue input records. Records may arrive in any order, any number of times
139	   * and any number per request.
140	   *
141	   *  - a record whose (tick, unit, command) key is already stored is a
142	   *    duplicate: counted, never re-applied, and it cannot change the state;
143	   *  - a record for a tick beyond the frontier is stored for later;
144	   *  - a record for a tick at or below the frontier triggers one rollback to the
145	   *    earliest such tick, then a recomputation back to the frontier;
146	   *  - a record for an unknown unit, an out-of-range tick or a malformed command
147	   *    is rejected with a reason and leaves the state untouched.
148	   */
149	  submitInputs(matchId, raw, key) {
150	    const record = this.match(matchId);
151	    sim.exactKeys(raw, ['inputs'], 'body');
152	    if (!Array.isArray(raw.inputs)) {
153	      throw new ValidationError('inputs must be an array');
154	    }
155	    return this.idempotent(key, `submit-inputs:${matchId}`, raw, () => {
156	      if (raw.inputs.length === 0) {
157	        throw new ValidationError('inputs must be a non-empty array');
158	      }
159	      return this.processInputs(record, raw.inputs);
160	    });
161	  }
162	
163	  /**
164	   * The input pipeline shared by the match-wide and the session-scoped input
165	   * endpoints: validation, de-duplication, stat accounting and the single
166	   * rollback-and-rebuild pass for late records. When `options.session` is set, a
167	   * record whose unit is not bound to that session is rejected with
168	   * `wrong_session` instead of being applied; the global rules, ordering and
169	   * counters stay identical.
170	   */
171	  processInputs(record, entries, options = {}) {
172	    const matchId = record.config.id;
173	    const session = options.session || null;
174	    const frontier = this.store.readState(matchId).tick;
175	    const accepted = [];
176	    const duplicates = [];
177	    const rejected = [];
178	    let earliest = null;
179	    entries.forEach((entry, index) => {
180	      let input;
181	      try {
182	        input = sim.parseInputRecord(entry);
183	      } catch (error) {
184	        rejected.push({ index, message: error.message, reason: 'invalid_input' });
185	        return;
186	      }
187	      if (input.tick >= record.config.maxTicks) {
188	        rejected.push({
189	          index,
190	          message: `input tick ${input.tick} is outside the match length ${record.config.maxTicks}`,
191	          reason: 'out_of_range',
192	        });
193	        return;
194	      }
195	      if (!record.config.units.some((unit) => unit.id === input.unit)) {
196	        rejected.push({ index, message: `input references unknown unit ${input.unit}`, reason: 'unknown_unit' });
197	        return;
198	      }
199	      if (session && !session.units.includes(input.unit)) {
200	        rejected.push({
201	          index,
202	          message: `unit ${input.unit} does not belong to session ${session.id}`,
203	          reason: 'wrong_session',
204	        });
205	        return;
206	      }
207	      if (this.store.readInput(matchId, input.tick, input.unit, input.command.kind)) {
208	        duplicates.push({ command: input.command.kind, tick: input.tick, unit: input.unit });
209	        return;
210	      }
211	      input.arrival = this.store.countInputsBefore(matchId, record.config.maxTicks);
212	      this.store.insertInput(matchId, input, sim.stripInput(input));
213	      accepted.push({ command: input.command.kind, seq: input.seq, tick: input.tick, unit: input.unit });
214	      if (earliest === null || input.tick < earliest) {
215	        earliest = input.tick;
216	      }
217	    });
218	
219	    this.store.bumpStat(matchId, 'accepted', accepted.length);
220	    this.store.bumpStat(matchId, 'duplicates', duplicates.length);
221	    this.store.bumpStat(matchId, 'rejected', rejected.length);
222	
223	    let rollback = null;
224	    if (earliest !== null && earliest < frontier) {
225	      // A late input rewinds the match to the earliest affected tick and then
226	      // replays forward to the frontier it had reached before this request, so
227	      // accepting a late input never loses already simulated ticks.
228	      const rewound = this.rollback(matchId, earliest);
229	      const { frames } = this.resimulate(matchId, earliest, frontier, false);
230	      const after = this.store.readState(matchId);
231	      this.store.bumpStat(matchId, 'rollbacks', 1);
232	      rollback = { ...rewound, frames_recomputed: frames.length, hash_after: after.hash, tick: after.tick };
233	    }
234	    return {
235	      ...this.describe(record.config, this.store.readState(matchId)),
236	      accepted, duplicates, rejected, rollback,
237	    };
238	  }
239	
240	  /** Load a match's session or fail with 404; never returns null. */
241	  requireSession(matchId, sessionId) {
242	    this.match(matchId);
243	    const session = this.store.readSession(matchId, sessionId);
244	    if (!session) {
245	      throw new NotFoundError(`session ${sessionId} of match ${matchId} was not found`);
246	    }
247	    return session;
248	  }
249	
250	  describeSession(matchId, session) {
251	    return {
252	      match_id: matchId,
253	      session_id: session.id,
254	      status: session.status,
255	      units: session.units.slice(),
256	    };
257	  }
258	
259	  /**
260	   * Bind a session to one or more match units. Units must be a non-empty list of
261	   * distinct units of this match, and no unit may belong to another session, so
262	   * ownership is unique. Sessions are bookkeeping only: they never enter the
263	   * state hash or the replay document.
264	   */
265	  createSession(matchId, raw, key) {
266	    const record = this.match(matchId);
267	    sim.exactKeys(raw, ['id', 'units'], 'body');
268	    if (raw.id === undefined || raw.units === undefined) {
269	      throw new ValidationError('body must contain id and units');
270	    }
271	    const sessionId = sim.identifier(raw.id, 'session id');
272	    if (!Array.isArray(raw.units) || raw.units.length === 0) {
273	      throw new ValidationError('units must be a non-empty array');
274	    }
275	    const units = [];
276	    const seen = new Set();
277	    for (const entry of raw.units) {
278	      const unitId = sim.identifier(entry, 'session unit id');
279	      if (seen.has(unitId)) {
280	        throw new ValidationError(`session units must be unique: ${unitId}`);
281	      }
282	      seen.add(unitId);
283	      if (!record.config.units.some((unit) => unit.id === unitId)) {
284	        throw new ValidationError(`session references unknown unit ${unitId}`);
285	      }
286	      units.push(unitId);
287	    }
288	    units.sort();
289	    return this.idempotent(key, `create-session:${matchId}`, raw, () => {
290	      if (this.store.readSession(matchId, sessionId)) {
291	        throw new ConflictError(`session ${sessionId} already exists for match ${matchId}`);
292	      }
293	      for (const other of this.store.readSessions(matchId)) {
294	        const overlap = other.units.find((unitId) => seen.has(unitId));
295	        if (overlap) {
296	          throw new ConflictError(`unit ${overlap} already belongs to session ${other.id}`);
297	        }
298	      }
299	      const session = { id: sessionId, status: 'connected', units };
300	      this.store.insertSession(matchId, session);
301	      return this.describeSession(matchId, session);
302	    });
303	  }
304	
305	  /**
306	   * Submit inputs through a session. The format, de-duplication key, canonical
307	   * order, late-input rollback and counters are exactly those of the match-wide
308	   * endpoint; an input for a unit the session does not own is rejected with
309	   * reason `wrong_session`, and a disconnected session may not submit at all.
310	   */
311	  submitSessionInputs(matchId, sessionId, raw, key) {
312	    const session = this.requireSession(matchId, sessionId);
313	    sim.exactKeys(raw, ['inputs'], 'body');
314	    if (!Array.isArray(raw.inputs)) {
315	      throw new ValidationError('inputs must be an array');
316	    }
317	    return this.idempotent(key, `submit-session-inputs:${matchId}:${sessionId}`, raw, () => {
318	      if (session.status === 'disconnected') {
319	        throw new ConflictError(`session ${sessionId} is disconnected and cannot submit inputs`);
320	      }
321	      if (raw.inputs.length === 0) {
322	        throw new ValidationError('inputs must be a non-empty array');
323	      }
324	      return this.processInputs(this.match(matchId), raw.inputs, { session });
325	    });
326	  }
327	
328	  /** Mark a session disconnected; the match itself is unaffected. Idempotent. */
329	  disconnectSession(matchId, sessionId, raw, key) {
330	    const session = this.requireSession(matchId, sessionId);
331	    const body = raw === undefined || raw === null ? {} : raw;
332	    sim.exactKeys(body, [], 'body');
333	    return this.idempotent(key, `disconnect-session:${matchId}:${sessionId}`, body, () => {
334	      if (session.status !== 'disconnected') {
335	        this.store.setSessionStatus(matchId, sessionId, 'disconnected');
336	      }
337	      return this.describeSession(matchId, { ...session, status: 'disconnected' });
338	    });
339	  }
340	
341	  /**
342	   * Reconnect a session and stream the frames recorded *after* `after_tick`, at
343	   * most `limit` per call (default and maximum 1024), together with the
344	   * caught-up unit states and team damage. The session ends up `connected`; a
345	   * partial window reports `complete: false` and is paged by calling again with
346	   * the returned `next_tick`.
347	   *
348	   * The window is read from the recorded frame log and must be contiguous and
349	   * hash-consistent end to end; a gap or a recomputation mismatch is an
350	   * `integrity_failure` instead of an inconsistent catch-up.
351	   */
352	  resumeSession(matchId, sessionId, raw, key) {
353	    const session = this.requireSession(matchId, sessionId);
354	    sim.exactKeys(raw, ['after_tick', 'limit'], 'body');
355	    if (!Object.prototype.hasOwnProperty.call(raw, 'after_tick')) {
356	      throw new ValidationError('body must contain after_tick');
357	    }
358	    const afterTick = raw.after_tick;
359	    if (!Number.isInteger(afterTick) || afterTick < 0) {
360	      throw new ValidationError('after_tick must be a non-negative integer');
361	    }
362	    const limit = raw.limit === undefined ? sim.MAX_STEP : raw.limit;
363	    if (!Number.isInteger(limit) || limit < 1 || limit > sim.MAX_STEP) {
364	      throw new ValidationError(`limit must be an integer between 1 and ${sim.MAX_STEP}`);
365	    }
366	    return this.idempotent(key, `resume-session:${matchId}:${sessionId}`, raw, () => {
367	      const frontier = this.store.readState(matchId).tick;
368	      if (afterTick > frontier) {
369	        throw new ConflictError(`after_tick ${afterTick} is past the current tick ${frontier}`);
370	      }
371	      const frames = this.sessionFrames(matchId, afterTick, limit, frontier);
372	      if (session.status !== 'connected') {
373	        this.store.setSessionStatus(matchId, sessionId, 'connected');
374	      }
375	      const state = this.store.readState(matchId);
376	      const reached = afterTick + frames.length;
377	      const complete = reached >= frontier;
378	      const units = this.unitsAt(matchId, session.units, reached, state)
379	        .sort((left, right) => (left.id < right.id ? -1 : 1));
380	      return {
381	        complete,
382	        frames,
383	        match_id: matchId,
384	        next_tick: reached,
385	        session_id: sessionId,
386	        state_hash: complete ? state.hash : this.frameHashAt(matchId, reached),
387	        status: 'connected',
388	        team_damage: this.teamDamageAt(matchId, reached, state),
389	        units,
390	      };
391	    });
392	  }
393	
394	  /**
395	   * The recorded frame summaries strictly after `afterTick`, up to `limit`, in
396	   * tick order. The log must be contiguous from the requested point; the window
397	   * is re-derived in memory from the snapshot before it and must reproduce every
398	   * recorded hash - a divergence is an integrity failure rather than a silently
399	   * different catch-up. Nothing here mutates the frame log.
400	   */
401	  sessionFrames(matchId, afterTick, limit, frontier) {
402	    const end = Math.min(afterTick + limit, frontier);
403	    const byTick = new Map();
404	    for (const frame of this.store.readFramesFrom(matchId, afterTick + 1)) {
405	      byTick.set(frame.tick, frame);
406	    }
407	    const frames = [];
408	    for (let tick = afterTick + 1; tick <= end; tick += 1) {
409	      const frame = byTick.get(tick);
410	      if (!frame) {
411	        // Every tick up to the frontier must have a frame; a gap means the log
412	        // was corrupted and catch-up cannot be served continuously.
413	        throw new IntegrityError(`match ${matchId} is missing recorded frame ${tick}`);
414	      }
415	      frames.push({
416	        casualties: frame.delta.casualties, settled: frame.settled,
417	        state_hash: frame.state_hash, tick: frame.tick,
418	      });
419	    }
420	    if (frames.length > 0) {
421	      this.verifyWindow(matchId, afterTick, frames);
422	    }
423	    return frames;
424	  }
425	
426	  /**
427	   * Recompute the frames of a catch-up window in memory from the snapshot before
428	   * it and the stored input log, comparing each hash with the recorded one. This
429	   * is the read-only counterpart of the rollback rebuild: session catch-up never
430	   * trims or rewrites the frame log.
431	   */
432	  verifyWindow(matchId, afterTick, frames) {
433	    const state = this.snapshotAt(matchId, afterTick);
434	    const buckets = new Map();
435	    for (const input of this.store.readInputs(matchId)) {
436	      const bucket = buckets.get(input.tick);
437	      if (bucket) {
438	        bucket.push(input.body);
439	      } else {
440	        buckets.set(input.tick, [input.body]);
441	      }
442	    }
443	    for (const bucket of buckets.values()) {
444	      bucket.sort(sim.compareInputs);
445	    }
446	    for (const frame of frames) {
447	      const settled = buckets.get(state.tick) || [];
448	      sim.applyTick(state, settled);
449	      state.hash = sim.stateHash(state);
450	      if (state.tick !== frame.tick || state.hash !== frame.state_hash) {
451	        throw new IntegrityError(`frame ${frame.tick} of match ${matchId} does not recompute to its recorded hash`);
452	      }
453	    }
454	  }
455	
456	  /** Hash of the state *after* frame `tick`; 0 is the initial (frontier) hash. */
457	  frameHashAt(matchId, tick) {
458	    if (tick <= 0) {
459	      return sim.stateHash(sim.initialState(this.config(matchId)));
460	    }
461	    const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
462	    if (!frame) {
463	      throw new IntegrityError(`match ${matchId} has no recorded frame ${tick}`);
464	    }
465	    return frame.state_hash;
466	  }
467	
468	  /** Team damage at frame `tick`, taken from the frame snapshot when mid-window. */
469	  teamDamageAt(matchId, tick, current) {
470	    if (tick >= current.tick) {
471	      return { blue: current.teamDamage.blue, red: current.teamDamage.red };
472	    }
473	    if (tick <= 0) {
474	      return { blue: 0, red: 0 };
475	    }
476	    const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
477	    if (!frame) {
478	      throw new IntegrityError(`match ${matchId} has no recorded frame ${tick}`);
479	    }
480	    return { blue: frame.state.teams.blue, red: frame.state.teams.red };
481	  }
482	
483	  /** Snapshots of the session-owned units as they are at frame `tick`. */
484	  unitsAt(matchId, unitIds, tick, current) {
485	    let source;
486	    if (tick >= current.tick) {
487	      source = current.units;
488	    } else if (tick <= 0) {
489	      source = sim.initialState(this.config(matchId)).units;
490	    } else {
491	      const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
492	      if (!frame) {
493	        throw new IntegrityError(`match ${matchId} has no recorded frame ${tick}`);
494	      }
495	      source = {};
496	      for (const unit of frame.state.units) {
497	        source[unit.id] = unit;
498	      }
499	    }
500	    return unitIds.map((id) => {
501	      const unit = source[id];
502	      if (!unit) {
503	        throw new IntegrityError(`frame ${tick} of match ${matchId} is missing unit ${id}`);
504	      }
505	      return {
506	        alive: unit.health > 0, attacking: unit.attacking, health: unit.health,
507	        id: unit.id, position: unit.position, team: unit.team, velocity: unit.velocity,
508	      };
509	    });
510	  }
511	
512	  /**
513	   * Advance a match by `count` ticks (default 1).
514	   *
515	   * The frontier never passes `max_ticks`, and the simulation stops early when a
516	   * team is eliminated. Advancing a match that is not `running` is a 409.
517	   */
518	  advance(matchId, raw, key) {
519	    const config = this.config(matchId);
520	    const body = raw === undefined || raw === null ? { count: 1 } : raw;
521	    sim.exactKeys(body, ['count'], 'body');
522	    const count = body.count === undefined ? 1 : body.count;
523	    if (!Number.isInteger(count) || count < 1 || count > sim.MAX_STEP) {
524	      throw new ValidationError(`count must be an integer between 1 and ${sim.MAX_STEP}`);
525	    }
526	    return this.idempotent(key, `advance:${matchId}`, { count }, () => {
527	      const before = this.store.readState(matchId);
528	      if (before.status !== 'running') {
529	        throw new ConflictError(`match ${matchId} is ${before.status} and cannot advance`);
530	      }
531	      const target = Math.min(before.tick + count, config.maxTicks);
532	      const { frames } = this.resimulate(matchId, before.tick, target, false);
533	      const updated = this.store.readState(matchId);
534	      return {
535	        ...this.describe(config, updated),
536	        advanced: frames.length,
537	        frames: frames.map((frame) => ({
538	          casualties: frame.delta.casualties, settled: frame.settled,
539	          state_hash: frame.state_hash, tick: frame.tick,
540	        })),
541	        state_hash: updated.hash,
542	      };
543	    });
544	  }
545	
546	  /**
547	   * Explicit rollback: rewind the match to `tick` by discarding every frame after
548	   * it. Input records are never discarded, so the next `POST /tick` replays them
549	   * and reproduces exactly the hashes recorded before the rollback.
550	   */
551	  rollback(matchId, tick) {
552	    const record = this.match(matchId);
553	    if (!Number.isInteger(tick) || tick < 0 || tick > record.config.maxTicks) {
554	      throw new ValidationError(`tick must be an integer between 0 and ${record.config.maxTicks}`);
555	    }
556	    const before = this.store.readState(matchId);
557	    if (tick > before.tick) {
558	      throw new ConflictError(`tick ${tick} is past the current tick ${before.tick}`);
559	    }
560	    this.resimulate(matchId, tick, tick, false);
561	    const after = this.store.readState(matchId);
562	    return {
563	      frames_recomputed: before.tick - tick,
564	      from_tick: before.tick, hash_after: after.hash, hash_before: before.hash,
565	      match_id: matchId, tick: after.tick, to_tick: tick,
566	    };
567	  }
568	
569	  /** The whole match as a portable replay document. */
570	  replayFile(matchId) {
571	    const record = this.match(matchId);
572	    const frames = this.store.readFrames(matchId).map((frame) => ({
573	      delta: frame.delta, settled: frame.settled, settled_inputs: frame.inputs,
574	      state_hash: frame.state_hash, tick: frame.tick,
575	    }));
576	    return replay.buildFile(record.config, frames, this.store.readInputs(matchId));
577	  }
578	
579	  /**
580	   * `POST /matches/{id}/verify` accepts either `{"match_id": "..."}` to
581	   * re-simulate a stored match, or `{"replay": {...}}` for an uploaded replay.
582	   */
583	  verify(raw) {
584	    sim.exactKeys(raw, ['match_id', 'replay'], 'body');
585	    if (raw.replay !== undefined && raw.match_id !== undefined) {
586	      throw new ValidationError('provide either match_id or replay, not both');
587	    }
588	    if (raw.replay !== undefined) {
589	      return this.verifyDocument(raw.replay);
590	    }
591	    if (typeof raw.match_id !== 'string' || raw.match_id.length === 0) {
592	      throw new ValidationError('match_id must be a non-empty string');
593	    }
594	    return this.verifyDocument(this.replayFile(raw.match_id));
595	  }
596	
597	  verifyDocument(document) {
598	    const result = replay.verifyDocument(document);
599	    const stored = this.store.readMatch(result.config.id);
600	    const mismatches = result.mismatches.slice();
601	    let recordedHash = null;
602	    if (stored && stored.tick === result.state.tick) {
603	      recordedHash = stored.stateHash;
604	      if (recordedHash !== result.state_hash) {
605	        mismatches.push({
606	          kind: 'state_hash',
607	          message: 'replayed final state does not match the stored match state',
608	          recorded: recordedHash, recomputed: result.state_hash, tick: result.state.tick,
609	        });
610	      }
611	    }
612	    return {
613	      consistent: mismatches.length === 0,
614	      final_state_hash: result.state_hash,
615	      match_id: result.config.id,
616	      mismatches,
617	      recorded_state_hash: recordedHash,
618	      replay_hash: result.replay_hash,
619	      ticks_replayed: result.frames.length,
620	    };
621	  }
622	
623	  /**
624	   * Rebuild the frame log from `resumeTick` up to `targetTick`.
625	   *
626	   * Frames after `resumeTick` are discarded and re-derived from the snapshot at
627	   * `resumeTick` plus the stored input records. Every rebuilt frame that already
628	   * existed must keep its hash; a divergence means the log or the engine changed
629	   * and is reported as `integrity_failure` instead of silently changing results.
630	   *
631	   * `extend` lets the match simulate past `targetTick` until a team is eliminated
632	   * or `max_ticks` is reached. `POST /tick` does not extend: stopping exactly at
633	   * the requested tick is what makes rollback-then-advance reproduce hashes.
634	   */
635	  resimulate(matchId, resumeTick, targetTick, extend = false) {
636	    const config = this.config(matchId);
637	    if (targetTick < resumeTick) {
638	      throw new IntegrityError(`cannot resimulate ${matchId} backwards from ${resumeTick} to ${targetTick}`);
639	    }
640	    const expected = new Map();
641	    for (const frame of this.store.readFramesFrom(matchId, resumeTick + 1)) {
642	      expected.set(frame.tick, frame.state_hash);
643	    }
644	    // `resumeTick` is a *frame* number: resuming continues from the state that
645	    // frame recorded, and must read it before the log is trimmed.
646	    const state = this.snapshotAt(matchId, resumeTick);
647	    const resumeStatus = state.status;
648	    this.store.deleteFramesFrom(matchId, resumeTick + 1);
649	    const buckets = new Map();
650	    for (const input of this.store.readInputs(matchId)) {
651	      const bucket = buckets.get(input.tick);
652	      if (bucket) {
653	        bucket.push(input.body);
654	      } else {
655	        buckets.set(input.tick, [input.body]);
656	      }
657	    }
658	    for (const bucket of buckets.values()) {
659	      bucket.sort(sim.compareInputs);
660	    }
661	
662	    state.status = 'running';
663	    const boundary = extend ? config.maxTicks : targetTick;
664	    const rebuilt = [];
665	    let endedNaturally = false;
666	    // Iteration `produced` applies the inputs of tick `produced - 1` and records
667	    // frame `produced`.
668	    for (let produced = resumeTick + 1; produced <= boundary; produced += 1) {
669	      const aliveAtStart = Object.values(state.units).filter((unit) => unit.health > 0).length;
670	      const settled = buckets.get(state.tick) || [];
671	      const delta = sim.applyTick(state, settled);
672	      state.hash = sim.stateHash(state);
673	      const recorded = expected.get(state.tick);
674	      if (recorded !== undefined && recorded !== state.hash) {
675	        throw new IntegrityError(
676	          `frame ${state.tick} of match ${matchId} recomputed to ${state.hash} but was recorded as ${recorded}`,
677	        );
678	      }
679	      const frame = {
680	        alive: aliveAtStart,
681	        delta,
682	        inputs: settled.map(sim.canonicalInput),
683	        settled: settled.length >= aliveAtStart,
684	        state: {
685	          teams: { blue: state.teamDamage.blue, red: state.teamDamage.red },
686	          tick: state.tick,
687	          units: Object.values(state.units).map((unit) => ({
688	            attacking: unit.attacking, health: unit.health, id: unit.id,
689	            position: unit.position, team: unit.team, velocity: unit.velocity,
690	          })),
691	        },
692	        state_hash: state.hash,
693	        tick: state.tick,
694	      };
695	      this.store.insertFrame(matchId, frame);
696	      rebuilt.push(frame);
697	      if (state.status !== 'running') {
698	        endedNaturally = true;
699	        break;
700	      }
701	    }
702	    if (state.tick === targetTick && !endedNaturally) {
703	      // A timeline that stops exactly at the requested frontier keeps the status
704	      // that frontier had, instead of inventing one from the tick count.
705	      state.status = resumeStatus;
706	    }
707	    // The frontier hash is always the hash of the state the frontier holds, so a
708	    // rolled-back match reports the same hash that its frame held before.
709	    state.hash = sim.stateHash(state);
710	    this.store.writeState(matchId, state, {});
711	    return { frames: rebuilt, state };
712	  }
713	
714	  /**
715	   * State snapshot *after* frame `tick`: the initial state for tick 0, otherwise
716	   * the snapshot frame `tick` itself stored. A missing frame is a hard failure
717	   * because every later frame depends on it.
718	   */
719	  snapshotAt(matchId, tick) {
720	    const config = this.config(matchId);
721	    if (tick <= 0) {
722	      return sim.initialState(config);
723	    }
724	    const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
725	    if (!frame) {
726	      throw new IntegrityError(`match ${matchId} has no recorded frame ${tick} to resume from`);
727	    }
728	    const state = sim.initialState(config);
729	    state.teamDamage = { blue: frame.state.teams.blue, red: frame.state.teams.red };
730	    state.tick = frame.state.tick;
731	    for (const unit of frame.state.units) {
732	      state.units[unit.id] = { ...unit };
733	    }
734	    return state;
735	  }
736	}
